import React, {useEffect, useState} from 'react'
import axios from 'axios';
import { useParams } from 'react-router';

function UpdateItem() {
  const {id} = useParams();
  const [formData, setFormData] = useState({
    itemId: '',
    itemName: '',
    itemCategory: '',
    itemQty: '',
    itemDetails: '',
    itemImage: null
  });

  useEffect(() => {
    const fetchItem = async () => {
      try {
        const response = await axios.get(`http://localhost:8080/inventory/${id}`);
        const itemData = response.data;
        setFormData({
            itemId: itemData.itemId || '',
            itemName: itemData.itemName || '',
            itemCategory: itemData.itemCategory || '',
            itemQty: itemData.itemQty || '',
            itemDetails: itemData.itemDetails || '',
            itemImage: null
        });
      } catch (err) {
        console.error("Error fetching item:", err);
      }
    };

    fetchItem();
  }, [id]);

  const onInputChange = (e) => {
    const { name, value, files } = e.target;
    setFormData({
      ...formData,
      [name]: files ? files[0] : value
    });
  }

  const onSubmit = async (e) => {
    e.preventDefault();
    
    const data = new FormData();
    
    data.append("itemDetails", JSON.stringify({
      itemId: formData.itemId,
      itemName: formData.itemName,
      itemCategory: formData.itemCategory,
      itemQty: formData.itemQty,
      itemDetails: formData.itemDetails
    }));
    
    if (formData.itemImage) {
      data.append("file", formData.itemImage);
    }

    try {
      const response = await axios.put(`http://localhost:8080/inventory/${id}`, data);
        alert("Item updated successfully!")
        window.location.href="/allitems";
      }catch(err) {
        console.error("Error updating item:", err);
        alert("Error updating item");
      }

    }

      
  return (
    <div className="add-item-container">
      <p className="auth_topic">Update Item</p>

      <div className="form_container">
        <form id="itemForm" onSubmit={(e) => onSubmit(e)}>
          {/* Item ID */}
          <label htmlFor="itemId">Item ID:</label>
          <br />
          <input
            type="text"
            id="itemId"
            name="itemId"
            value={itemId}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Name */}
          <label htmlFor="itemName">Item Name:</label>
          <br />
          <input
            type="text"
            id="itemName"
            name="itemName"
            value={itemName}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Category */}
          <label htmlFor="itemCategory">Item Category:</label>
          <br />
          <select
            id="itemCategory"
            name="itemCategory"
            value={itemCategory}
            onChange={(e) => onInputChange(e)}
            required
          >
            <option value="" disabled>
              Select Item Category
            </option>
            <option value="Apparel & Fashion">Apparel & Fashion</option>
            <option value="Electronics & Gadgets">Electronics & Gadgets</option>
            <option value="Health & Beauty">Health & Beauty</option>
            <option value="Food & Dining">Food & Dining</option>
            <option value="Home & Furniture">Home & Furniture</option>
          </select>
          <br /><br />

          {/* Item Quantity */}
          <label htmlFor="itemQty">Item Quantity:</label>
          <br />
          <input
            type="number"
            id="itemQty"
            name="itemQty"
            value={itemQty}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Details */}
          <label htmlFor="itemDetails">Item Details:</label>
          <br />
          <textarea
            id="itemDetails"
            name="itemDetails"
            value={itemDetails}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Image */}
          <label htmlFor="itemImage">Item Image:</label>
          <br />
          <input
            type="file"
            id="itemImage"
            name="itemImage"
            onChange={(e) => onInputChange(e)}
            accept="image/*"
            required
          />
          <br /><br />

          {/* Submit Button */}
          <button type="submit" className="form_btn">
            Add Item
          </button>
        </form>
      </div>
    </div>
  );
}



export default UpdateItem
